: {name: string , parameters: {}, description: string , strict: true} } ] }) }; fetch( https://api.moonshot.cn/v1/chat/completions , options) .then(res = res.json()) .then(res = console.log(res)) .catch(err = console.error(err)); ?php $curl = curl_init(); curl_setopt_array($curl, [ CURLOPT_URL = https://api.moonshot.cn/v1/chat/completions , CURLOPT_RETURNTRANSFER = true, CURLOPT_ENCODING = , CURLOPT_MAXREDIRS = 10, CURLOPT_TIMEOUT = 30, CURLOPT_HTTP_VERSION = CURL_HTTP_VERSION_1_1, CURLOPT_CUSTOMREQUEST = POST , CURLOPT_POSTFIELDS = json_encode([ model = kimi-k3 , messages = [ [ role = user , content = 你好 , name = null, partial = false ] ], tools = [ [ type = function , function = [ name = string , parameters = [ ], description = string , strict = true ] ] ] ]), CURLOPT_HTTPHEADER = [ Authorization: Bearer token , Content-Type: application/json ], ]); $response = curl_exec($curl); $err = curl_error($curl); curl_close($curl); if ($err) { echo cURL Error #: . $err; } else { echo $response; } package main import ( fmt strings net/http io ) func main() { url := https://api.moonshot.cn/v1/chat/completions payload := strings.NewReader( {
