 }
 }
 ]
} ) req, _ := http.NewRequest( POST , url, payload) req.Header.Add( Authorization , Bearer token ) req.Header.Add( Content-Type , application/json ) res, _ := http.DefaultClient.Do(req) defer res.Body.Close() body, _ := io.ReadAll(res.Body) fmt.Println(string(body)) } HttpResponse String response = Unirest.post( https://api.moonshot.cn/v1/chat/completions ) .header( Authorization , Bearer token ) .header( Content-Type , application/json ) .body( {
