} ) .asString(); require uri require net/http url = URI( https://api.moonshot.cn/v1/chat/completions ) http = Net::HTTP.new(url.host, url.port) http.use_ssl = true request = Net::HTTP::Post.new(url) request[ Authorization ] = Bearer token request[ Content-Type ] = application/json request.body = {
